/* Name comparison (doc/spec_FS2.md §6, doc/spec_Foundation_API.md §11.7).
 * casefold_table.h is generated by foundation/lib/fnd/gen_casefold.py from
 * the same C+F table as tools/fs2, so the fs service, libfnd and the host
 * tool fold names alike. */
#include "name.h"

#include "casefold_table.h"

fnd_status fnd_utf8_next(const uint8_t *s, uint32_t len, uint32_t *pos, uint32_t *cp) {
    uint32_t i = *pos;
    if (i >= len)
        return FND_END;
    uint32_t c = s[i];
    uint32_t need, min;
    if (c < 0x80) {
        *cp = c;
        *pos = i + 1;
        return FND_OK;
    } else if ((c & 0xE0) == 0xC0) {
        need = 1, min = 0x80, c &= 0x1F;
    } else if ((c & 0xF0) == 0xE0) {
        need = 2, min = 0x800, c &= 0x0F;
    } else if ((c & 0xF8) == 0xF0) {
        need = 3, min = 0x10000, c &= 0x07;
    } else {
        return FND_E_BAD_PATH;
    }
    if (len - i - 1 < need)
        return FND_E_BAD_PATH;
    for (uint32_t k = 1; k <= need; ++k) {
        uint32_t b = s[i + k];
        if ((b & 0xC0) != 0x80)
            return FND_E_BAD_PATH;
        c = (c << 6) | (b & 0x3F);
    }
    if (c < min || c > 0x10FFFF || (c >= 0xD800 && c <= 0xDFFF))
        return FND_E_BAD_PATH;
    *cp = c;
    *pos = i + 1 + need;
    return FND_OK;
}

uint32_t fnd_casefold(uint32_t cp, uint32_t out[3]) {
    uint32_t lo = 0, hi = FND_CASEFOLD_COUNT;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        uint32_t from = fnd_cf_from[mid];
        if (from == cp) {
            uint32_t to = fnd_cf_to[mid];
            if (!(to & 0x80000000u)) {
                out[0] = to;
                return 1;
            }
            const uint32_t *m = &fnd_cf_multi[(to & 0xFFFFu) * 3u];
            uint32_t n = 0;
            while (n < 3 && m[n])
                out[n] = m[n], ++n;
            return n;
        }
        if (from < cp)
            lo = mid + 1;
        else
            hi = mid;
    }
    out[0] = cp;
    return 1;
}

/* Folded scalars of a valid UTF-8 string, one at a time. */
typedef struct {
    const uint8_t *s;
    uint32_t len, pos;
    uint32_t buf[3];
    uint32_t n, i;
} fold_iter;

static int fold_next(fold_iter *it, uint32_t *cp) {
    if (it->i == it->n) {
        uint32_t c;
        if (fnd_utf8_next(it->s, it->len, &it->pos, &c) != FND_OK)
            return 0;
        it->n = fnd_casefold(c, it->buf);
        it->i = 0;
    }
    *cp = it->buf[it->i++];
    return 1;
}

static void fold_init(fold_iter *it, const uint8_t *s, uint32_t len) {
    it->s = s, it->len = len, it->pos = 0, it->n = 0, it->i = 0;
}

int fnd_name_key_equal(const uint8_t *a, uint32_t alen, const uint8_t *b, uint32_t blen) {
    fold_iter x, y;
    fold_init(&x, a, alen);
    fold_init(&y, b, blen);
    for (;;) {
        uint32_t ca, cb;
        int ha = fold_next(&x, &ca), hb = fold_next(&y, &cb);
        if (ha != hb)
            return 0;
        if (!ha)
            return 1;
        if (ca != cb)
            return 0;
    }
}

uint32_t fnd_name_key_hash(const uint8_t *s, uint32_t len) {
    fold_iter it;
    uint32_t h = 2166136261u, c;
    fold_init(&it, s, len);
    while (fold_next(&it, &c))
        h = (h ^ c) * 16777619u;
    return h;
}

fnd_status fnd_name_check(const uint8_t *s, uint32_t len, uint32_t *chars) {
    uint32_t pos = 0, n = 0, c;
    fnd_status st;
    if (len == 0)
        return FND_E_BAD_PATH;
    while ((st = fnd_utf8_next(s, len, &pos, &c)) == FND_OK) {
        if (c == '/' || c < 0x20 || (c >= 0x7F && c <= 0x9F))
            return FND_E_BAD_PATH;
        ++n;
    }
    if (st != FND_END)
        return FND_E_BAD_PATH;
    if ((len == 1 && s[0] == '.') || (len == 2 && s[0] == '.' && s[1] == '.'))
        return FND_E_BAD_PATH;
    if (n > 256 || len > 1024)
        return FND_E_NAME_TOO_LONG;
    *chars = n;
    return FND_OK;
}

static uint32_t cstr_len(const char *s) {
    uint32_t n = 0;
    while (s[n])
        ++n;
    return n;
}

static uint32_t utf8_put(uint32_t c, uint8_t *o) {
    if (c < 0x80) {
        o[0] = (uint8_t)c;
        return 1;
    }
    if (c < 0x800) {
        o[0] = (uint8_t)(0xC0 | (c >> 6)), o[1] = (uint8_t)(0x80 | (c & 0x3F));
        return 2;
    }
    if (c < 0x10000) {
        o[0] = (uint8_t)(0xE0 | (c >> 12)), o[1] = (uint8_t)(0x80 | ((c >> 6) & 0x3F));
        o[2] = (uint8_t)(0x80 | (c & 0x3F));
        return 3;
    }
    o[0] = (uint8_t)(0xF0 | (c >> 18)), o[1] = (uint8_t)(0x80 | ((c >> 12) & 0x3F));
    o[2] = (uint8_t)(0x80 | ((c >> 6) & 0x3F)), o[3] = (uint8_t)(0x80 | (c & 0x3F));
    return 4;
}

fnd_status fnd_name_fold(const char *name, char *out, uint32_t cap, uint32_t *len) {
    const uint8_t *s = (const uint8_t *)name;
    uint32_t n = cstr_len(name), pos = 0, need = 0, c;
    fnd_status st;
    /* Validate and measure first, so that `out` is untouched on failure. */
    while ((st = fnd_utf8_next(s, n, &pos, &c)) == FND_OK) {
        uint32_t f[3], k = fnd_casefold(c, f);
        uint8_t tmp[4];
        for (uint32_t i = 0; i < k; ++i)
            need += utf8_put(f[i], tmp);
    }
    if (st != FND_END)
        return FND_E_BAD_PATH;
    if (need + 1 > cap) {
        *len = need + 1;
        return FND_E_LIMIT;
    }
    fold_iter it;
    uint32_t o = 0;
    fold_init(&it, s, n);
    while (fold_next(&it, &c))
        o += utf8_put(c, (uint8_t *)out + o);
    out[o] = 0;
    *len = o;
    return FND_OK;
}

int fnd_name_equal(const char *a, const char *b) {
    uint32_t al = cstr_len(a), bl = cstr_len(b), pos = 0, c;
    fnd_status st;
    while ((st = fnd_utf8_next((const uint8_t *)a, al, &pos, &c)) == FND_OK) {
    }
    if (st != FND_END)
        return 0;
    pos = 0;
    while ((st = fnd_utf8_next((const uint8_t *)b, bl, &pos, &c)) == FND_OK) {
    }
    if (st != FND_END)
        return 0;
    return fnd_name_key_equal((const uint8_t *)a, al, (const uint8_t *)b, bl);
}

/* Folded scalars of a pattern or a name, for fnd_name_match. Names are at
 * most 256 scalars, each folding to at most 3. */
#define MATCH_MAX 1024u

static int fold_all(const char *s, uint32_t *out, uint32_t *n) {
    uint32_t len = cstr_len(s), pos = 0, c, k = 0;
    fnd_status st;
    while ((st = fnd_utf8_next((const uint8_t *)s, len, &pos, &c)) == FND_OK) {
        uint32_t f[3], m = fnd_casefold(c, f);
        if (k + m > MATCH_MAX)
            return 0;
        for (uint32_t i = 0; i < m; ++i)
            out[k++] = f[i];
    }
    *n = k;
    return st == FND_END;
}

int fnd_name_match(const char *pattern, const char *name) {
    uint32_t p[MATCH_MAX], s[MATCH_MAX], pn, sn;
    if (!fold_all(pattern, p, &pn) || !fold_all(name, s, &sn))
        return 0;
    /* Greedy match with backtracking to the last '*'. */
    uint32_t i = 0, j = 0, star = 0xFFFFFFFFu, mark = 0;
    while (j < sn) {
        if (i < pn && (p[i] == '?' || p[i] == s[j]) && p[i] != '*') {
            ++i, ++j;
        } else if (i < pn && p[i] == '*') {
            star = i++;
            mark = j;
        } else if (star != 0xFFFFFFFFu) {
            i = star + 1;
            j = ++mark;
        } else {
            return 0;
        }
    }
    while (i < pn && p[i] == '*')
        ++i;
    return i == pn;
}
